mapper.select:
select cb.id, cb.category_id as categoryId, cb.brand_id as brandId, cb.create_time as createTime, c.name as categoryName, b.name as brandName, b.logo as logo from category_brand cb inner join category c on c.id = cb.category_id inner join brand b on b.id = cb.brand_id
cb.is_deleted = 0
and cb.category_id = #{categoryId}
and cb.brand_id = #{brandId}
limit #{offset}, #{limit}

select count(*) from category_brand cb

    cb.is_deleted = 0

        and cb.category_id = #{categoryId}


        and cb.brand_id = #{brandId}

select
b.* from category_brand cb left join brand b on  cb.brand_id=b.id
    where category_id =#{categoryId} and cb.is_deleted=0 order by cb.id desc;
